using Azure;
using Azure.Storage.Blobs;
using Azure.Storage.Queues;
using System.Text.Json;

namespace LmAzure.Cloud;

public sealed class AzureRun : IDisposable
{
    private readonly AzureSession _session; private readonly string _ledger; private readonly string _runId; private readonly DateTimeOffset _createdUtc = DateTimeOffset.UtcNow; private readonly List<(string Kind, string Name)> _owned = new(); private bool _closed;
    internal AzureRun(AzureSession session, string ledgerPath, bool mock)
    {
        _session = session; _ledger = ledgerPath; _runId = Guid.NewGuid().ToString("N")[..12];
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(ledgerPath))!);
        using var stream = new FileStream(ledgerPath, FileMode.CreateNew, FileAccess.Write, FileShare.None);
        WriteLedger(stream);
    }
    public ResourceTable CreateContainer(string suffix) { EnsureWrite(); EnsureCapacity(); var name = Name(suffix); try { using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15)); var response = _session.BlobContainer(name).CreateAsync(metadata: new Dictionary<string, string> { ["lmazure_test"] = _runId }, cancellationToken: timeout.Token).GetAwaiter().GetResult(); if (response.GetRawResponse().Status != 201) throw new AzureCloudException("container was not newly created"); Claim("blob", name); return One(name, "blob", "created"); } catch (AzureCloudException) { throw; } catch (Exception ex) { throw new AzureCloudException("container creation failed", ex); } }
    public ResourceTable CreateQueue(string suffix) { EnsureWrite(); EnsureCapacity(); var name = Name(suffix); try { using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15)); var response = _session.Queue(name).CreateAsync(metadata: new Dictionary<string, string> { ["lmazure_test"] = _runId }, cancellationToken: timeout.Token).GetAwaiter().GetResult(); if (response.Status != 201) throw new AzureCloudException("queue was not newly created"); Claim("queue", name); return One(name, "queue", "created"); } catch (AzureCloudException) { throw; } catch (Exception ex) { throw new AzureCloudException("queue creation failed", ex); } }
    public ResourceTable Tag(string name, string key, string value) { EnsureWrite(); EnsureOwned(name); if (string.IsNullOrWhiteSpace(key) || key.Length > 128 || key.Contains(':')) throw new AzureCloudException("invalid metadata key"); try { if (!_session.OwnsMetadataAsync(_owned.First(x => x.Name == name).Kind, name, _runId).GetAwaiter().GetResult()) throw new AzureCloudException("resource ownership metadata check failed"); using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15)); if (_owned.First(x => x.Name == name).Kind == "blob") _session.BlobContainer(name).SetMetadataAsync(new Dictionary<string, string> { [key] = value, ["lmazure_test"] = _runId }, cancellationToken: timeout.Token).GetAwaiter().GetResult(); else _session.Queue(name).SetMetadataAsync(new Dictionary<string, string> { [key] = value, ["lmazure_test"] = _runId }, cancellationToken: timeout.Token).GetAwaiter().GetResult(); return One(name, "owned", "tagged"); } catch (AzureCloudException) { throw; } catch (Exception ex) { throw new AzureCloudException("resource tagging failed", ex); } }
    public ResourceTable Delete(string name) { EnsureWrite(); EnsureOwned(name); var item = _owned.First(x => x.Name == name); try { if (!_session.OwnsMetadataAsync(item.Kind, name, _runId).GetAwaiter().GetResult()) throw new AzureCloudException("resource ownership metadata check failed"); using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15)); if (item.Kind == "blob") _session.BlobContainer(name).DeleteAsync(cancellationToken: timeout.Token).GetAwaiter().GetResult(); else _session.Queue(name).DeleteAsync(cancellationToken: timeout.Token).GetAwaiter().GetResult(); _owned.Remove(item); Persist(); return One(name, item.Kind, "deleted"); } catch (AzureCloudException) { throw; } catch (Exception ex) { throw new AzureCloudException("resource deletion failed", ex); } }
    public void Cleanup() { EnsureWrite(); var failures = new List<string>(); foreach (var item in _owned.ToArray()) { try { if (!_session.OwnsMetadataAsync(item.Kind, item.Name, _runId).GetAwaiter().GetResult()) { failures.Add(item.Name); continue; } using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15)); if (item.Kind == "blob") _session.BlobContainer(item.Name).DeleteAsync(cancellationToken: timeout.Token).GetAwaiter().GetResult(); else _session.Queue(item.Name).DeleteAsync(cancellationToken: timeout.Token).GetAwaiter().GetResult(); _owned.Remove(item); } catch (RequestFailedException ex) when (ex.Status == 404) { _owned.Remove(item); } catch { failures.Add(item.Name); } } Persist(); if (failures.Count != 0) throw new AzureCloudException("cleanup left owned resources in the ledger"); File.Delete(_ledger); }
    private void Claim(string kind, string name) { if (_owned.Count >= 16) throw new AzureCloudException("run ownership limit exceeded"); _owned.Add((kind, name)); Persist(); }
    private void EnsureCapacity() { if (_owned.Count >= 16) throw new AzureCloudException("run ownership limit exceeded"); }
    private void EnsureOwned(string name) { if (!_owned.Any(x => x.Name == name && x.Name.StartsWith("lmazure-", StringComparison.Ordinal))) throw new AzureCloudException("resource is not owned by this run"); }
    private string Name(string suffix) { if (string.IsNullOrWhiteSpace(suffix) || suffix.Length > 42 || !suffix.All(c => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-')) throw new AzureCloudException("invalid resource suffix"); return $"lmazure-{_runId}-{suffix.ToLowerInvariant()}"; }
    private ResourceTable One(string name, string kind, string status) => new([ResourceTable.Row(name, kind, _session.Region, status, 1, 0, false, true, true, AzureSession.MaskId(name))]);
    private void WriteLedger(Stream stream)
    {
        using var writer = new Utf8JsonWriter(stream); writer.WriteStartObject(); writer.WriteString("run_id", _runId); writer.WriteString("subscription", _session.Subscription); writer.WriteString("blob_endpoint", _session.BlobEndpoint); writer.WriteString("queue_endpoint", _session.QueueEndpoint); writer.WriteString("created_utc", _createdUtc); writer.WriteStartArray("owned"); foreach (var item in _owned) { writer.WriteStartObject(); writer.WriteString("kind", item.Kind); writer.WriteString("name", item.Name); writer.WriteEndObject(); } writer.WriteEndArray(); writer.WriteEndObject(); writer.Flush();
    }
    private void Persist() { var temp = _ledger + ".tmp-" + Guid.NewGuid().ToString("N"); using (var stream = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None)) WriteLedger(stream); if (new FileInfo(temp).Length > 1024 * 1024) { File.Delete(temp); throw new AzureCloudException("run ledger exceeds 1 MiB"); } File.Move(temp, _ledger, true); }
    private void EnsureWrite() { if (_closed) throw new ObjectDisposedException(nameof(AzureRun)); _session.EnsureWrite(); }
    public void Dispose() { if (!_closed) { try { Cleanup(); } finally { _closed = true; _session.Unregister(this); } } }
}
